import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level Google Font loading
const { fontFamily: montserratFamily } = loadMontserrat();

// Helper functions for muscle path generation
const getMusclePath = (w: number) => {
  const topWidth = 6;
  const bottomWidth = 6;
  return `
    M ${100 - topWidth},20
    C ${100 - topWidth - w * 0.15},120 ${100 - w},180 ${100 - w},250
    C ${100 - w},320 ${100 - bottomWidth - w * 0.15},380 ${100 - bottomWidth},480
    L ${100 + bottomWidth},480
    C ${100 + bottomWidth + w * 0.15},380 ${100 + w},320 ${100 + w},250
    C ${100 + w},180 ${100 + topWidth + w * 0.15},120 ${100 + topWidth},20
    Z
  `;
};

const getFiberPath = (t: number, w: number) => {
  const xTop = 100 + t * 4;
  const xMid = 100 + t * w * 0.95;
  const xBottom = 100 + t * 4;
  return `
    M ${xTop},20
    C ${100 + t * (w * 0.12)},120 ${xMid},180 ${xMid},250
    C ${xMid},320 ${100 + t * (w * 0.12)},380 ${xBottom},480
  `;
};

// Muscle SVG Component (Sub-renderer)
const MuscleSVG: React.FC<{
  width: number;
  height: number;
  W: number;
  health: number;
  muscleColor: string;
  atrophyColor: string;
  pulseScale: number;
  idSuffix: string;
}> = ({
  width,
  height,
  W,
  health,
  muscleColor,
  atrophyColor,
  pulseScale,
  idSuffix,
}) => {
  const mainPath = getMusclePath(W);
  const fiberOffsets = [-0.85, -0.65, -0.45, -0.25, 0, 0.25, 0.45, 0.65, 0.85];

  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 200 500"
      style={{
        overflow: "visible",
        transform: `scale(${pulseScale})`,
        transition: "none",
      }}
    >
      <defs>
        {/* Atrophy Muscle Gradient */}
        <linearGradient
          id={`atrophy-grad-${idSuffix}`}
          x1="0"
          y1="0"
          x2="1"
          y2="0"
        >
          <stop offset="0%" stopColor="#2c1a1c" />
          <stop offset="30%" stopColor="#523537" />
          <stop offset="50%" stopColor="#7d5356" />
          <stop offset="70%" stopColor="#523537" />
          <stop offset="100%" stopColor="#2c1a1c" />
        </linearGradient>

        {/* Healthy Muscle Gradient */}
        <linearGradient
          id={`healthy-grad-${idSuffix}`}
          x1="0"
          y1="0"
          x2="1"
          y2="0"
        >
          <stop offset="0%" stopColor="#400508" />
          <stop offset="25%" stopColor={muscleColor} />
          <stop offset="50%" stopColor="#ffa6ab" />
          <stop offset="75%" stopColor={muscleColor} />
          <stop offset="100%" stopColor="#400508" />
        </linearGradient>

        {/* Tendon Highlight Vertical Overlay Gradient */}
        <linearGradient
          id={`tendon-overlay-grad-${idSuffix}`}
          x1="0"
          y1="0"
          x2="0"
          y2="1"
        >
          <stop offset="0%" stopColor="#ffd4d6" stopOpacity="0.95" />
          <stop offset="8%" stopColor="#e29196" stopOpacity="0.6" />
          <stop offset="16%" stopColor="#400508" stopOpacity="0" />
          <stop offset="84%" stopColor="#400508" stopOpacity="0" />
          <stop offset="92%" stopColor="#e29196" stopOpacity="0.6" />
          <stop offset="100%" stopColor="#ffd4d6" stopOpacity="0.95" />
        </linearGradient>
      </defs>

      {/* Main Muscle Belly Atrophy base */}
      <path
        d={mainPath}
        fill={`url(#atrophy-grad-${idSuffix})`}
        style={{ transition: "none" }}
      />

      {/* Main Muscle Belly Healthy overlay */}
      <path
        d={mainPath}
        fill={`url(#healthy-grad-${idSuffix})`}
        opacity={health}
        style={{ transition: "none" }}
      />

      {/* Muscle Fibers */}
      <g style={{ transition: "none" }}>
        {fiberOffsets.map((t, index) => {
          const pathD = getFiberPath(t, W);
          const strokeW = interpolate(health, [0, 1], [0.8, 2.5]);
          const strokeColor = `rgba(255, ${interpolate(
            health,
            [0, 1],
            [180, 240]
          )}, ${interpolate(health, [0, 1], [180, 240])}, ${interpolate(
            health,
            [0, 1],
            [0.12, 0.55]
          )})`;
          return (
            <path
              key={index}
              d={pathD}
              fill="none"
              stroke={strokeColor}
              strokeWidth={strokeW}
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          );
        })}
      </g>

      {/* Tendon Overlays */}
      <path
        d={mainPath}
        fill={`url(#tendon-overlay-grad-${idSuffix})`}
        style={{ mixBlendMode: "screen", transition: "none" }}
      />
    </svg>
  );
};

// Main Schema


export type MuscleTransformationProps = Record<string, any>;

const MuscleTransformation: React.FC<MuscleTransformationProps> = ({
  backgroundColor = "#0d0d0f",
  transparentBackground = false,
  durationInSeconds = 8,
  leftLabel = "0 WEEKS: ATROPHY",
  rightLabel = "12 WEEKS: HYPERTROPHY",
  clockColor = "#ffffff",
  accentColor = "#ff9d23",
  muscleColor = "#e63946",
  atrophyColor = "#8f585a",
  showLabels = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Muscle Intro (Frame 0 - 35)
  const introSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
    durationInFrames: 35,
  });
  const currentScale = introSpring;
  const currentOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Ticking Week Counter & Transformation Progress (Frame 30 - 130)
  const progressStart = 30;
  const progressEnd = 130;

  const clockOpacity = interpolate(frame, [15, 35], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const minuteAngle = interpolate(
    frame,
    [progressStart, progressEnd],
    [0, 360 * 6],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const hourAngle = interpolate(
    frame,
    [progressStart, progressEnd],
    [0, 360 * 0.5],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Clock Sweep Progress
  const sweepProgress = interpolate(
    frame,
    [progressStart, progressEnd],
    [0.0, 1.0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Muscle Transformation Parameters (Width, Health, Scale)
  const currentW = interpolate(
    frame,
    [progressStart, progressEnd],
    [18, 72],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const currentHealth = interpolate(
    frame,
    [progressStart, progressEnd],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Organic pulsing that gets stronger as the muscle becomes healthier
  const pulseAmp = interpolate(currentHealth, [0, 1], [0.003, 0.015]);
  const pulseScale = 1 + pulseAmp * Math.sin(frame * 0.07);

  // Growth-based scaling to physically expand the overall boundary of the muscle
  const muscleGrowthScale = interpolate(currentHealth, [0, 1], [0.9, 1.15]);
  const totalMuscleScale = currentScale * muscleGrowthScale * pulseScale;

  // Background Sizing & Layout
  const radialBg = `radial-gradient(circle at 50% 50%, #16161e 0%, ${backgroundColor} 100%)`;
  const bgColor = transparentBackground ? "transparent" : radialBg;

  const muscleHeight = height * 0.7;
  const muscleWidth = muscleHeight * 0.45;
  const clockSize = height * 0.45;

  // Responsive Layout Styles
  const muscleWrapperStyle: React.CSSProperties = {
    position: "absolute",
    left: width * 0.28 - muscleWidth / 2,
    top: height * 0.5 - muscleHeight / 2,
    width: muscleWidth,
    height: muscleHeight,
    transform: "rotate(-5deg)",
    opacity: currentOpacity,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    filter:
      currentHealth > 0
        ? `drop-shadow(0 0 ${30 * currentHealth}px ${muscleColor})`
        : "none",
    transition: "none",
  };

  const clockWrapperStyle: React.CSSProperties = {
    position: "absolute",
    left: width * 0.72 - clockSize / 2,
    top: height * 0.38 - clockSize / 2,
    width: clockSize,
    height: clockSize,
    opacity: clockOpacity,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    transition: "none",
  };

  const progressPanelStyle: React.CSSProperties = {
    position: "absolute",
    left: width * 0.72 - (width * 0.34) / 2,
    top: height * 0.68,
    width: width * 0.34,
    display: "flex",
    flexDirection: "column",
    opacity: clockOpacity,
    transition: "none",
  };

  const labelRowStyle: React.CSSProperties = {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "12px",
    fontFamily: montserratFamily,
    transition: "none",
  };

  const leftLabelActiveStyle: React.CSSProperties = {
    color: "#a0a0aa",
    fontSize: `${height * 0.018}px`,
    fontWeight: 600,
    letterSpacing: "1.5px",
    opacity: interpolate(currentHealth, [0, 1], [1, 0.4]),
    transition: "none",
  };

  const rightLabelActiveStyle: React.CSSProperties = {
    color: accentColor,
    fontSize: `${height * 0.018}px`,
    fontWeight: 700,
    letterSpacing: "1.5px",
    opacity: interpolate(currentHealth, [0, 1], [0.4, 1]),
    textShadow: `0 0 10px ${accentColor}${Math.round(
      interpolate(currentHealth, [0, 1], [0, 40])
    )}`,
    transition: "none",
  };

  const progressBarTrackStyle: React.CSSProperties = {
    width: "100%",
    height: "8px",
    backgroundColor: "rgba(255, 255, 255, 0.08)",
    borderRadius: "4px",
    position: "relative",
    overflow: "hidden",
    transition: "none",
  };

  const progressBarFillStyle: React.CSSProperties = {
    position: "absolute",
    left: 0,
    top: 0,
    bottom: 0,
    width: `${sweepProgress * 100}%`,
    background: `linear-gradient(90deg, ${atrophyColor} 0%, ${muscleColor} 100%)`,
    borderRadius: "4px",
    boxShadow: `0 0 12px ${muscleColor}`,
    transition: "none",
  };

  const statusBadgeStyle: React.CSSProperties = {
    marginTop: "20px",
    padding: "10px 16px",
    borderRadius: "6px",
    backgroundColor: "rgba(255, 255, 255, 0.02)",
    border: "1px solid rgba(255, 255, 255, 0.06)",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    transition: "none",
  };

  const statusTitleStyle: React.CSSProperties = {
    color: "#71717a",
    fontSize: `${height * 0.014}px`,
    fontWeight: 600,
    letterSpacing: "1px",
    textTransform: "uppercase",
    transition: "none",
  };

  const statusValueStyle: React.CSSProperties = {
    color: currentHealth < 0.5 ? atrophyColor : muscleColor,
    fontSize: `${height * 0.016}px`,
    fontWeight: 700,
    letterSpacing: "1px",
    textTransform: "uppercase",
    transition: "none",
  };

  const statusText = currentHealth < 0.5 ? "Atrophy State" : "Hypertrophy State";
  const ticks = Array.from({ length: 12 });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: montserratFamily,
        overflow: "hidden",
      }}
    >
      {/* Left Column: Transforming Muscle */}
      <div style={muscleWrapperStyle}>
        <MuscleSVG
          width={muscleWidth}
          height={muscleHeight}
          W={currentW}
          health={currentHealth}
          muscleColor={muscleColor}
          atrophyColor={atrophyColor}
          pulseScale={totalMuscleScale}
          idSuffix="main"
        />
      </div>

      {/* Right Column: Clock Visualizer */}
      <div style={clockWrapperStyle}>
        <svg
          width="100%"
          height="100%"
          viewBox="0 0 360 360"
          style={{ overflow: "visible", transition: "none" }}
        >
          <defs>
            {/* Ambient Background Glow for Clock */}
            <radialGradient id="clock-glow" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor={accentColor} stopOpacity="0.08" />
              <stop offset="100%" stopColor={accentColor} stopOpacity="0" />
            </radialGradient>
          </defs>

          {/* Clock Base Background Panel */}
          <circle cx="180" cy="180" r="145" fill="url(#clock-glow)" />
          <circle
            cx="180"
            cy="180"
            r="130"
            fill="rgba(255,255,255,0.01)"
            stroke="rgba(255,255,255,0.06)"
            strokeWidth="1.5"
          />

          {/* 12 Hour Ticks */}
          {ticks.map((_, i) => {
            const isQuarter = i % 3 === 0;
            return (
              <g
                key={i}
                transform={`rotate(${i * 30}, 180, 180)`}
                style={{ transition: "none" }}
              >
                {isQuarter ? (
                  <line
                    x1="180"
                    y1="50"
                    x2="180"
                    y2="66"
                    stroke={clockColor}
                    strokeWidth="3.5"
                    strokeLinecap="round"
                    opacity="0.75"
                  />
                ) : (
                  <line
                    x1="180"
                    y1="50"
                    x2="180"
                    y2="60"
                    stroke={clockColor}
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    opacity="0.25"
                  />
                )}
              </g>
            );
          })}

          {/* Glowing Time Progress Sweeping Outer Arc */}
          <circle
            cx="180"
            cy="180"
            r="145"
            fill="none"
            stroke={accentColor}
            strokeWidth="5.5"
            strokeDasharray={911}
            strokeDashoffset={911 * (1 - sweepProgress)}
            strokeLinecap="round"
            transform="rotate(-90, 180, 180)"
            style={{
              filter: `drop-shadow(0 0 8px ${accentColor})`,
              transition: "none",
            }}
          />

          {/* Dynamic Sweeping Arrowhead */}
          <g
            transform={`rotate(${-90 + sweepProgress * 360}, 180, 180)`}
            style={{ transition: "none" }}
          >
            <polygon
              points="174,27 187,35 174,43"
              fill={accentColor}
              style={{
                filter: `drop-shadow(0 0 6px ${accentColor})`,
                transition: "none",
              }}
            />
          </g>

          {/* Rotating Hands */}
          {/* Hour Hand */}
          <line
            x1="180"
            y1="180"
            x2="180"
            y2="124"
            stroke={clockColor}
            strokeWidth="4.5"
            strokeLinecap="round"
            transform={`rotate(${hourAngle}, 180, 180)`}
            opacity="0.85"
            style={{ transition: "none" }}
          />

          {/* Minute Hand */}
          <line
            x1="180"
            y1="180"
            x2="180"
            y2="100"
            stroke={clockColor}
            strokeWidth="2.5"
            strokeLinecap="round"
            transform={`rotate(${minuteAngle}, 180, 180)`}
            opacity="0.6"
            style={{ transition: "none" }}
          />

          {/* Centered Pivot Pin */}
          <circle
            cx="180"
            cy="180"
            r="7"
            fill="#111115"
            stroke={clockColor}
            strokeWidth="2.5"
          />
        </svg>
      </div>

      {/* Metadata / Labels & Progress Dashboard */}
      {showLabels && (
        <div style={progressPanelStyle}>
          <div style={labelRowStyle}>
            <span style={leftLabelActiveStyle}>{leftLabel}</span>
            <span style={rightLabelActiveStyle}>{rightLabel}</span>
          </div>
          <div style={progressBarTrackStyle}>
            <div style={progressBarFillStyle} />
          </div>
          <div style={statusBadgeStyle}>
            <span style={statusTitleStyle}>Current State</span>
            <span style={statusValueStyle}>{statusText}</span>
          </div>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default MuscleTransformation;